import {resultTrashTools} from './result-trash.js';
import {richText,sectionStats,indentSelection} from './test-content.js';
import {simulatorTools} from './simulators.js';
import {adminTools} from './admin-ui.js';
import {API,PUBLIC_KEY} from './config.js';
const $=s=>document.querySelector(s),h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>crypto.randomUUID();
const TYPES={single:'Одна правильна',multi:'Кілька правильних',match:'Відповідність',sequence:'Послідовність',groups:'Категорії'},STATUS={active:'Триває',paused:'На паузі',closed:'Завершено',cancelled:'Скасовано'};
const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',tests:'<rect x="5" y="3" width="14" height="18" rx="3"/><path d="M9 8h6M9 12h6M9 16h3"/>',live:'<path d="m9 7 8 5-8 5Z"/><rect x="2" y="3" width="20" height="18" rx="5"/>',journal:'<path d="M3 4h18v16H3ZM3 9h18M9 9v11M15 9v11"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v2"/>',catalog:'<path d="M3 5h7l2 3h9v12H3Z"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',logout:'<path d="M9 4H4v16h5m6-12 4 4-4 4m-6-4h10"/>',chart:'<path d="M4 20V10h4v10m4 0V4h4v16m4 0V8"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.tests}</svg>`;
icons.simulators='<rect x="3" y="3" width="18" height="14" rx="3"/><path d="M8 21h8m-4-4v4m-2-14 6 3-6 3Z"/>';
const S={token:sessionStorage.getItem('kd-auth')||'',user:null,view:'entry',catalog:[],tests:[],sessions:[],users:[],results:[],edit:null,qi:0,live:null,journal:null,lookup:null,play:null,attempt:sessionStorage.getItem('kd-attempt')||'',draft:null,review:null,sending:false,filter:'',classFilter:'',loginMode:false};
let pollBusy=false,timer=null,noticeTimer;
async function api(action,data={}){const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json',apikey:PUBLIC_KEY,...(S.token?{'x-kd-token':S.token}:{})},body:JSON.stringify({action,...data})});const b=await r.json();if(!r.ok)throw Error(b.error||'Не вдалося виконати запит.');return b;}
function toast(s){$('#notice').textContent=s;$('#notice').classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').classList.remove('show'),5500);}
function modal(content){$('#modal').innerHTML=`<button class="modal-close" data-act="closeModal" aria-label="Закрити">×</button>${content}`;$('#modal').showModal();}
const button=(text,act,cls='primary',attrs='')=>`<button class="${cls}" data-act="${act}" ${attrs}>${text}</button>`;
const field=(label,body)=>`<label class="field"><span>${label}</span>${body}</label>`;
const input=(name,value='',extra='')=>`<input name="${name}" value="${h(value)}" ${extra}>`;
const options=(xs,value)=>xs.map(x=>`<option ${x===value?'selected':''} value="${h(x)}">${h(x)}</option>`).join('');
const date=s=>new Date(s).toLocaleDateString('uk-UA',{day:'2-digit',month:'2-digit',year:'numeric'});
const brand=`<a href="./" class="brand" data-act="brand"><img src="./assets/favicon.svg" alt=""><span>КіберДім<small>Навігатор знань</small></span></a>`;
const empty=(title,body)=>`<div class="empty">${icon('tests')}<h3>${title}</h3><p>${body}</p></div>`;
function entry(){return `<div class="entry"><header>${brand}<div class="toolbar">${button('Симулятори','nav','outline','data-view="simulators"')}<button class="outline" data-act="loginToggle">${S.loginMode?'До тестування':'Увійти в кабінет'}</button></div></header><main class="welcome"><section class="welcome-copy"><span class="eyebrow">МАЛЕНЬКІ КРОКИ. ВЕЛИКІ ВІДКРИТТЯ.</span><h1>Знання, що<br>додають <em>впевненості.</em></h1><p>Перевіряйте себе, знаходьте сильні сторони<br class="desktop"> та навчайтеся у власному темпі.</p><div class="welcome-art"><div class="orbit one"></div><div class="orbit two"></div><img src="./assets/bee-wave.gif" alt="Усміхнена бджілка вітає учнів"><span class="art-note">Кожна відповідь —<br><b>наступний крок.</b></span><span class="float-chip">${icon('check')} Можеш більше!</span></div></section><section class="join-card">${S.loginMode?`<span class="badge blue">${icon('lock')} Особистий простір</span><h2>Раді бачити вас!</h2><p>Вхід для вчителів та учнів, які мають обліковий запис.</p><form data-form="login">${field('Логін',input('login','', 'autocomplete="username" required'))}${field('Пароль',input('password','', 'type="password" autocomplete="current-password" required'))}<button class="primary wide">Увійти</button></form><p class="small">Забули пароль? Зверніться до адміністратора платформи для отримання тимчасового пароля.</p>`:`<span class="badge blue">${icon('live')} Тестування наживо</span><h2>${S.lookup?'Майже готово!':'Приєднайся до тесту'}</h2><p>${S.lookup?h(S.lookup.title):'Введи 6-значний код, який повідомив учитель.'}</p><form data-form="${S.lookup?'join':'lookup'}">${field('Код тесту',input('code',S.code||new URLSearchParams(location.search).get('pin')||'','class="pin-input" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="000000" autocomplete="off" required'))}${S.lookup?`${field('Твій клас',`<select name="className" required>${options(S.lookup.classes,S.user?.class_name)}</select>`)}${field('Прізвище та ім’я',input('name',S.user?.name||'','placeholder="Наприклад, Коваленко Софія" autocomplete="name" required'))}`:''}<button class="primary wide">${S.lookup?'Приєднатися':'Знайти тест'}</button></form>${S.lookup?button('Ввести інший код','resetLookup','text-button'):''}<div class="join-foot">${icon('lock')} Без реєстрації. Лише код і твоє ім’я.</div>`}</section></main><footer>Створено для навчання, відкриттів і подолання освітніх втрат.</footer></div>`;}
function shell(body){const student=S.user.role==='student',nav=student?[['home','Мій простір'],['chart','Карта досягнень'],['simulators','Симулятори'],['settings','Налаштування']]:[['home','Простір учителя'],['tests','Мої тести'],['live','Тестування наживо'],['journal','Журнал та звіти'],...(S.user.role==='admin'?[['users','Користувачі'],['catalog','Класи та предмети']]:[]),['simulators','Симулятори'],['settings','Налаштування']];return `<div class="app-shell"><aside>${brand}<div class="sidebar-label">${student?'ТВІЙ МАРШРУТ':'РОБОЧИЙ ПРОСТІР'}</div><nav>${nav.map(([v,t])=>button(icon(v)+t,'nav',S.view===v?'nav-item selected':'nav-item',`data-view="${v}"`)).join('')}</nav><div class="sidebar-bottom"><div class="tiny-hex">${icon('check')}</div><p>Навчаємося сьогодні.<br><b>Зростаємо щодня.</b></p></div></aside><div class="workspace"><header class="topbar"><span>${student?'Простір учня':S.user.role==='admin'?'Адміністратор · Учитель':'Простір учителя'}</span><div class="profile"><span class="avatar">${h(S.user.name.slice(0,1))}</span><span>${h(S.user.name)}</span><button class="icon-button" data-act="logout" aria-label="Вийти">${icon('logout')}</button></div></header><main>${body}</main></div></div>`;}
function heading(k,title,desc='',action=''){return `<div class="page-heading"><div><span class="eyebrow">${k}</span><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`;}
function home(){if(S.user.role==='student')return `${heading('ТВІЙ ОСВІТНІЙ ПРОСТІР','Привіт, досліднику!','Нові знання починаються з цікавості.')}<div class="hero"><div><span class="badge">Сьогодні можна більше</span><h2>Твій наступний<br>крок до знань</h2><p>Приєднуйся до тесту вчителя.<br>Результат збережеться у твоїй карті досягнень.</p>${button('Ввести код тесту','joinFromProfile')}</div><img src="./assets/bee-wave.gif" alt="Бджілка"></div><div class="section-title"><h2>Останні результати</h2></div>${historyList()}`;
return `${heading('НАВЧАННЯ З РОЗУМІННЯМ','Ваш простір для відкриттів','Створюйте тести, помічайте прогрес і допомагайте зростати.',button(icon('plus')+' Створити тест','newTest'))}<div class="hero"><div><span class="badge">КіберДім · Разом до знань</span><h2>Кожна відповідь<br>розповідає більше.</h2><p>Знаходьте сильні сторони учнів<br>і перетворюйте помилки на наступні кроки.</p>${button('Відкрити мої тести','nav','primary','data-view="tests"')}</div><img src="./assets/bee-wave.gif" alt="Бджілка — ваш помічник"></div><div class="stats"><article>${icon('tests')}<b>${S.tests.length}</b><span>у вашій бібліотеці</span></article><article>${icon('live')}<b>${S.sessions.filter(s=>['active','paused'].includes(s.status)).length}</b><span>активних сеансів</span></article><article>${icon('chart')}<b>${S.sessions.filter(s=>['closed','cancelled'].includes(s.status)).length}</b><span>завершених сеансів</span></article></div><div class="section-title"><h2>Мої тести</h2>${button('Усі тести','nav','text-button','data-view="tests"')}</div>${testCards(S.tests.slice(0,3))}`;}
function testCards(tests){return tests.length?`<div class="test-grid">${tests.map(({data:t})=>`<article class="test-card"><div class="card-top"><span class="square-icon">${icon('tests')}</span><span class="badge">${h(t.grade)} клас</span></div><p class="small blue-text">${h(t.subject)}</p><h3>${h(t.title)}</h3><p>${h(t.topic||'Діагностика знань')}</p><div class="card-meta">${t.questions.length} запитань <span>·</span> ${t.sections.length} розділів</div><div class="card-actions">${button('Редагувати','editTest','outline',`data-id="${h(t.id)}"`)}${button('Запустити','launch','primary',`data-id="${h(t.id)}"`)}${button('Видалити','trashTest','text-button danger',`data-id="${h(t.id)}"`)}</div></article>`).join('')}</div>`:empty('Тут починається ваша бібліотека','Створіть перший тест: додайте запитання, бали та правила проходження.');}
function tests(){return `${button('Видалені тести','openDeleted','text-button')}${heading('ОСОБИСТА БІБЛІОТЕКА','Мої тести','Ваші тести доступні учням лише після запуску за кодом.',button(icon('plus')+' Створити тест','newTest'))}<input class="search" aria-label="Пошук тестів" placeholder="Знайти за назвою чи темою" id="search" value="${h(S.filter)}"><div id="test-list">${testCards(S.tests.filter(x=>(x.data.title+' '+x.data.topic).toLowerCase().includes(S.filter.toLowerCase())))}</div>`;}
function newQuestion(type='single',section=S.edit.sections[0].id){const opts=Array.from({length:3},()=>({id:uid(),text:'',image:''}));return {id:uid(),type,section,text:'',image:'',points:1,seconds:type==='single'?30:45,options:opts,groups:['Група 1','Група 2','Група 3'],correct:type==='single'?opts[0].id:['multi','sequence'].includes(type)?(type==='multi'?opts.slice(0,2):opts).map(o=>o.id):Object.fromEntries(opts.map((o,i)=>[o.id,`Група ${i+1}`])),explanation:''};}
function freshTest(){const id=uid();S.edit={id:uid(),title:'',subject:S.user.subjects[0]||'Інформатика',topic:'',grade:9,scale:'points',timer:true,feedback:false,shuffleQuestions:true,shuffleAnswers:true,sections:[{id,name:'Розділ 1',advice:'',take:0,uniqueTypes:false}],questions:[]};S.edit.questions.push(newQuestion());S.qi=0;S.view='builder';render();}
const bindInput=(key,value,scope='q',extra='')=>`<input data-${scope}="${key}" value="${h(value)}" ${extra}>`;
const check=(label,key,value,scope='test')=>`<label class="toggle"><input type="checkbox" data-${scope}="${key}" ${value?'checked':''}><span>${label}</span></label>`;
function sectionStatus(s){return `<span>У банку: <b>${s.count}</b> · Учню: <b>${s.shown}</b></span>${s.issue?`<small class="section-warning">${h(s.issue)}</small>`:''}`;}
function builderSections(){return sectionStats(S.edit).map(s=>`<section class="builder-section ${s.id===S.edit.questions[S.qi]?.section?'current':''}"><h4>${h(s.name)} <span class="section-count">${s.count}</span></h4><div class="section-fill">${sectionStatus(s)}</div>${S.edit.questions.flatMap((q,i)=>q.section===s.id?[button(`<b>${i+1}</b><span>${h(q.text||'Нове запитання')}<small>${TYPES[q.type]} · ${q.points} б.</small></span>`,'selectQuestion',`question-link ${i===S.qi?'selected':''}`,`data-index="${i}"`)]:[]).join('')}${button('+ Запитання','addQuestion','text-button section-add',`data-section-id="${h(s.id)}" aria-label="Додати запитання в розділ ${h(s.name)}"`)}</section>`).join('');}
function refreshBuilderSections(){const box=$('#builder-sections');if(box)box.innerHTML=builderSections();document.querySelectorAll('[data-section-fill]').forEach(el=>{const stat=sectionStats(S.edit)[Number(el.dataset.sectionFill)];if(stat)el.innerHTML=sectionStatus(stat);});}
const formatOptions=value=>`<option value="text" ${value!=='code'?'selected':''}>Текст</option><option value="code" ${value==='code'?'selected':''}>Код · моноширинний шрифт</option>`;
function builder(){const t=S.edit,q=t.questions[S.qi];return `${heading('КОНСТРУКТОР ТЕСТІВ',h(t.title)||'Новий тест','Налаштуйте зміст і правила. Кожне запитання має власну вартість.',button('Зберегти тест','saveTest'))}<div class="builder-layout"><div class="question-sidebar"><h3>Запитання <span>${t.questions.length}</span></h3><div id="builder-sections">${builderSections()}</div>${button('Розділи та вибірка','sections','text-button wide')}</div><div class="builder-content"><section class="panel"><h2>Про тест</h2><div class="form-grid">${field('Назва тесту',bindInput('title',t.title,'test','maxlength="160"'))}${field('Предмет',bindInput('subject',t.subject,'test','list="subjects"'))}<datalist id="subjects">${options(S.catalog.filter(x=>x.kind==='subject').map(x=>x.name))}</datalist>${field('Тема',bindInput('topic',t.topic,'test'))}${field('Клас (рік навчання)',bindInput('grade',t.grade,'test','type="number" min="1" max="12"'))}</div><div class="settings-row">${check('Таймер запитань','timer',t.timer)}${check('Показувати правильні відповіді','feedback',t.feedback)}${check('Перемішувати запитання','shuffleQuestions',t.shuffleQuestions)}${check('Перемішувати варіанти','shuffleAnswers',t.shuffleAnswers)}</div>${field('Оцінювання',`<select data-test="scale"><option value="points" ${t.scale==='points'?'selected':''}>Бальна шкала · 1–12</option><option value="level" ${t.scale==='level'?'selected':''}>Рівні · П, С, Д, В</option></select>`)}</section><section class="panel question-editor"><div class="section-title"><h2>Запитання ${S.qi+1}</h2>${t.questions.length>1?button('Видалити','deleteQuestion','text-button danger'):''}</div><div class="type-picker">${Object.entries(TYPES).map(([key,name])=>button(name,'changeType',q.type===key?'type selected':'type',`data-type="${key}"`)).join('')}</div><div class="form-grid thirds">${field('Розділ',`<select data-q="section">${t.sections.map(s=>`<option value="${s.id}" ${q.section===s.id?'selected':''}>${h(s.name)}</option>`).join('')}</select>`)}${field('Вартість, балів',bindInput('points',q.points,'q','type="number" min="1" max="100"'))}${field('Час, секунд',bindInput('seconds',q.seconds,'q','type="number" min="5" max="600" step="5"'))}</div>${field('Формат запитання',`<select data-q="format">${formatOptions(q.format)}</select>`)}${field('Текст запитання',`<textarea data-q="text" data-preserve class="${q.format==='code'?'code-editor':''}" rows="5" spellcheck="false" placeholder="Що мають з’ясувати учні?">
${h(q.text)}</textarea>`)}<p class="small">Переноси рядків і відступи зберігаються. У форматі «Код»: Tab — 4 пробіли, Shift+Tab — прибрати відступ. Для переходу до наступного поля: Esc, потім Tab.</p>${field('Зображення до запитання · HTTPS або Google Drive',bindInput('image',q.image,'q','type="url" placeholder="https://…"'))}<h3>${q.type==='sequence'?'Кроки у правильній послідовності':'Варіанти відповідей'}</h3><p class="small">${q.type==='single'?'Позначте одну правильну відповідь.':q.type==='multi'?'Позначте щонайменше дві правильні відповіді.':q.type==='sequence'?'Розташуйте кроки правильно. Учень отримає їх перемішаними.':'Вкажіть правильну пару або категорію для кожного елемента.'}</p>${['match','groups'].includes(q.type)?field('Назви правих частин / категорій — по одній у рядку',`<textarea data-q="groups" rows="3">${h(q.groups.join('\n'))}</textarea>`):''}<div class="editor-options">${q.options.map((o,i)=>`<div class="editor-option"><div class="option-toolbar"><span class="option-letter">${String.fromCharCode(65+i)}</span>${['single','multi'].includes(q.type)?`<label class="check-label"><input data-correct="${o.id}" type="${q.type==='single'?'radio':'checkbox'}" name="correct" ${(q.type==='single'?q.correct===o.id:q.correct.includes(o.id))?'checked':''}>Правильна</label>`:q.type==='sequence'?`<span>${i+1}</span>${button('Вище','optionUp','text-button',`data-index="${i}" ${i===0?'disabled':''}`)}${button('Нижче','optionDown','text-button',`data-index="${i}" ${i===q.options.length-1?'disabled':''}`)}`:`<select data-map="${o.id}" aria-label="Правильна група">${q.type==='groups'?`<option value="" ${q.correct[o.id]===''?'selected':''}>Зайве слово</option>`:''}${options(q.groups,q.correct[o.id])}</select>`}${button('×','removeOption','text-button',`data-index="${i}" aria-label="Видалити варіант"`)}</div>${field('Формат варіанта '+String.fromCharCode(65+i),`<select data-option="${i}" data-key="format">${formatOptions(o.format)}</select>`)}${field('Текст варіанта '+String.fromCharCode(65+i),`<textarea data-option="${i}" data-key="text" data-preserve rows="4" spellcheck="false" class="${o.format==='code'?'code-editor':''}" placeholder="Текст або код варіанта">
${h(o.text)}</textarea>`)}<input data-option="${i}" data-key="image" value="${h(o.image)}" placeholder="Посилання на зображення (необов’язково)" type="url"></div>`).join('')}</div>${button(icon('plus')+' Додати варіант','addOption','outline')}${field('Пояснення після відповіді (якщо показ увімкнено)',`<textarea data-q="explanation" rows="2">
${h(q.explanation)}</textarea>`)}</section><div class="save-bar">${button('До бібліотеки','nav','outline','data-view="tests"')}${button('Зберегти тест','saveTest')}</div></div></div>`;}
function sectionModal(){modal(`<h2>Розділи та вибірка</h2><p>0 — усі запитання розділу. Вибірка формується окремо для кожного учня.</p>${S.edit.sections.map((s,i)=>`<section class="section-settings"><h3>Розділ ${i+1}</h3><div class="section-fill" data-section-fill="${i}">${sectionStatus(sectionStats(S.edit)[i])}</div>${field('Назва',`<input data-section="${i}" data-key="name" value="${h(s.name)}">`)}${field('Скільки запитань показати',`<input type="number" min="0" data-section="${i}" data-key="take" value="${s.take}">`)}<label class="toggle"><input type="checkbox" data-section="${i}" data-key="uniqueTypes" ${s.uniqueTypes?'checked':''}>Без повтору типів</label>${field('Порада для повторення',`<textarea data-section="${i}" data-key="advice">${h(s.advice)}</textarea>`)}</section>`).join('')}<div class="actions">${button('Додати розділ','addSection','outline')}${button('Готово','doneSections')}</div>`);}
function liveList(){return `${heading('КЛАС НА ЗВ’ЯЗКУ','Тестування наживо','Один запуск — один PIN-код і окрема колонка журналу.',button('Видалені сеанси та результати','deletedResults','outline'))}<div class="session-list">${S.sessions.length?S.sessions.map(s=>`<article class="panel session-item"><span class="square-icon">${icon('live')}</span><div><h3>${h(s.title)}</h3><p>${h(s.classes.join(', '))} · ${date(s.created_at)}</p></div><span class="badge ${s.status==='active'?'blue':''}">${STATUS[s.status]}</span>${button('Відкрити звіт','openSession','outline',`data-id="${s.id}"`)}${resultUI.removeButton('session',s.id)}</article>`).join(''):empty('Ще немає сеансів','Відкрийте тест у своїй бібліотеці та натисніть «Запустити».')}</div>`;}
function live(){if(!S.live)return liveList();const {session:s,students}=S.live,done=students.filter(x=>x.done);return `${heading('ПУЛЬТ УЧИТЕЛЯ',h(s.title),h(s.subject)+' · '+h(s.classes.join(', ')),`<div class="toolbar">${button('Усі сеанси','backLive','outline')}${resultUI.removeButton('session',s.id)}</div>`)}<div class="session-hero"><div><span class="eyebrow">КОД ДЛЯ ПРИЄДНАННЯ</span><div class="large-pin">${s.code}</div><span class="badge">${STATUS[s.status]}</span></div><div class="session-controls">${button('Копіювати посилання','copyInvite','outline')}${s.status==='active'?button('Призупинити','sessionCommand','primary','data-command="pause"'):s.status==='paused'?button('Відновити','sessionCommand','primary','data-command="resume"'):''}${['active','paused'].includes(s.status)?`${button('Завершити','confirmEnd','outline','data-command="close"')}${button('Скасувати сеанс','confirmEnd','text-button danger','data-command="cancel"')}`:''}</div></div><div class="stats"><article><b>${students.length}</b><span>приєдналися</span></article><article><b>${done.length}</b><span>завершили</span></article><article><b>${done.length?Math.round(done.reduce((a,x)=>a+x.result.percent,0)/done.length)+'%':'—'}</b><span>середній результат</span></article></div><section class="panel"><div class="section-title"><h2>Результати учнів</h2>${button('Завантажити CSV','exportLive','outline')}</div><p class="small">Гостьові імена вводять самі учні. Позначка «Профіль» підтверджує вхід до облікового запису.</p><div class="table-wrap"><table><thead><tr><th>Учень</th><th>Клас</th><th>Прогрес</th><th>Результат</th><th></th></tr></thead><tbody>${students.map(x=>`<tr><td><strong>${h(x.name)}</strong><small>${x.userId?'Профіль':'Гість'}</small></td><td>${h(x.className)}</td><td>${x.index} / ${x.count}</td><td>${x.done?`<span class="result-pill">${s.scale==='level'?x.result.level:x.result.mark}</span> ${x.result.percent}%`:s.status==='cancelled'?'<b class="cancelled">С</b>':'У процесі'}</td><td>${x.done?button('Звіт','studentReport','text-button',`data-id="${x.id}"`):''}${resultUI.removeButton('result',x.id)}</td></tr>`).join('')||'<tr><td colspan="5">Очікуємо на учнів…</td></tr>'}</tbody></table></div></section><section class="panel"><h2>Розділи: що варто повторити</h2>${S.live.sections.map(sec=>{const a=done.flatMap(x=>x.result.sections).filter(x=>x.id===sec.id),max=a.reduce((n,x)=>n+x.total,0),score=a.reduce((n,x)=>n+x.score,0);return `<div class="analysis-row"><span>${h(sec.name)}</span><progress value="${score}" max="${max||1}"></progress><b>${max?Math.round(score/max*100)+'%':'—'}</b></div>`}).join('')}<p class="small">Розраховано за завершеними роботами з урахуванням вартості запитань.</p></section>`;}
function journal(){const j=S.journal||{columns:[],rows:[]},cols=j.columns.filter(x=>!S.classFilter||x.classes.includes(S.classFilter)),rows=j.rows.filter(x=>!S.classFilter||x.className===S.classFilter);return `${heading('ПРОГРЕС У ЦИФРАХ','Журнал та звіти','Кожен сеанс має власну колонку. Назва відкриває зведений звіт.',`<div class="toolbar">${button('Завантажити CSV','exportJournal','outline')}${button('Видалені сеанси та результати','deletedResults','outline')}</div>`)}<section class="panel"><div class="form-grid">${field('Клас',`<select id="journal-class"><option value="">Усі класи</option>${options([...new Set(j.rows.map(r=>r.className))],S.classFilter)}</select>`)}</div><div class="table-wrap"><table class="journal"><thead><tr><th>Учень</th><th>Клас</th>${cols.map(c=>`<th><small>${date(c.date)}</small>${button(h(c.title),'openSession','text-button',`data-id="${c.id}"`)}<small>${h(c.subject)} · приватний</small>${resultUI.removeButton('session',c.id,'Видалити сеанс')}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${h(r.name)}</strong><small>${r.verified?'Профіль':'Гість'}</small></td><td>${h(r.className)}</td>${cols.map(c=>{const x=r.cells[c.id];return `<td class="${x?.status==='cancelled'?'cancel-cell':''}">${x?.status==='done'?`<b>${c.scale==='level'?x.level:x.mark}</b>`:x?.status==='cancelled'?'<b class="cancelled">С</b>':x?.status==='active'?'…':x?.status==='missing'?'—':''}${x?.attemptId?resultUI.removeButton('result',x.attemptId,'Прибрати') :''}</td>`}).join('')}</tr>`).join('')||'<tr><td colspan="20">Оцінки з’являться після проходження тестів.</td></tr>'}</tbody></table></div><p class="small">С — сеанс скасовано до завершення роботи. Отримані до скасування оцінки зберігаються.</p></section>`;}
function reportView(r,title='',scale='points'){return `<div class="report-intro"><img src="./assets/bee-flight.gif" alt=""><div><span class="eyebrow">ТВІЙ НАСТУПНИЙ КРОК</span><h2>${h(title||'Роботу завершено!')}</h2><p>${r.score} / ${r.total} балів · ${r.percent}%</p></div><div class="grade-badge"><strong>${scale==='level'?r.level:r.mark}</strong><span>${scale==='level'?r.levelName:'балів'}</span></div></div><div class="report-rows">${r.sections.map(s=>`<article class="report-row"><div class="report-hex ${s.percent>=75?'high':s.percent>=50?'medium':'low'}"><b>${s.percent}%</b><small>${s.score} / ${s.total}</small></div><div><h3>${h(s.name)}</h3><p>${h(s.advice||'Використай знання у практичному завданні.')}</p></div></article>`).join('')}</div><div class="feedback-grid"><article><span class="badge blue">Твоя опора</span><p>${h(r.feedback.praise)}</p></article><article><span class="badge gold">Наступний крок</span>${r.feedback.focus.map(x=>`<h3>${h(x.name)}</h3><p>${h(x.advice)}</p>`).join('')||'<p>Усі розділи мають високий результат. Спробуй нове практичне завдання.</p>'}</article></div><p class="support">${h(r.feedback.support)}</p>${r.feedback.note?`<p class="small">${h(r.feedback.note)}</p>`:''}`;}
function historyList(){return S.results.length?`<div class="history-list">${S.results.map(r=>`<article class="panel session-item"><span class="result-pill">${r.percent}%</span><div><h3>${h(r.title)}</h3><p>${h(r.subject)} · ${date(r.date)}</p></div>${button('Мій звіт','historyReport','outline',`data-id="${r.id}"`)}</article>`).join('')}</div>`:empty('Тут з’явиться твій прогрес','Приєднайся до тесту після входу у профіль — результат збережеться тут.');}
function achievements(){const subjects=[...new Set(S.results.map(r=>r.subject))];return `${heading('КАРТА ДОСЯГНЕНЬ','Знання складаються у цілісну картину','Окрема карта для кожного предмета. Показано останній результат розділу.')} ${subjects.map(subject=>{const sections=new Map();S.results.filter(r=>r.subject===subject).forEach(r=>r.sections.forEach(s=>{if(!sections.has(s.name))sections.set(s.name,s)}));return `<section class="panel"><h2>${h(subject)}</h2><div class="honeycomb">${[...sections.values()].map(s=>`<article class="honey-cell ${s.percent>=75?'high':s.percent>=50?'medium':'low'}"><div><h3>${h(s.name)}</h3><b>${s.percent}%</b><small>${s.score} / ${s.total} балів</small></div></article>`).join('')}</div></section>`}).join('')||empty('Карта ще попереду','Після першого тесту тут з’являться твої стільники знань.')}`;}
function users(){return `${heading('АДМІНІСТРУВАННЯ','Користувачі платформи','Додавайте по одному або списком з Excel.',`<div class="toolbar">${button('Імпорт з Excel','openImport','outline')}${button(icon('plus')+' Додати користувача','newUser')}${button('Видалені','openDeleted','text-button')}</div>`)}<section class="panel"><div class="table-wrap"><table><thead><tr><th>Ім’я та логін</th><th>Роль</th><th>Предмети / клас</th><th>Доступ</th><th>Дії</th></tr></thead><tbody>${S.users.map(u=>`<tr><td><strong>${h(u.name)}</strong><small>${h(u.login)}</small></td><td>${{admin:'Адміністратор',teacher:'Учитель',student:'Учень'}[u.role]}</td><td>${h(u.class_name||u.subjects.join(', '))}</td><td>${u.blocked?'Призупинено':u.must_change?'Зміна пароля':'Активний'}</td><td>${button('Редагувати','editUser','text-button',`data-id="${u.id}"`)}${u.id!==S.user.id?`${button('Новий пароль','resetUser','text-button',`data-id="${u.id}"`)}${button(u.blocked?'Відновити доступ':'Призупинити','blockUser','text-button',`data-id="${u.id}"`)}${u.role!=='admin'?button('Видалити','trashUser','text-button danger',`data-id="${u.id}"`):''}`:''}</td></tr>`).join('')}</tbody></table></div><p class="small">Видалені акаунти можна відновити. Попередні результати зберігаються. Паролі захищені хешуванням.</p></section>`;}
function userModal(id){const u=S.users.find(x=>x.id===id);modal(`<h2>${u?'Картка користувача':'Новий користувач'}</h2><form data-form="user" data-id="${id||''}">${!u?`${field('Тип облікового запису','<select name="role"><option value="student">Учень</option><option value="teacher">Учитель</option></select>')}${field('Логін · латиниця',input('login','','required pattern="[a-zA-Z0-9_.@-]{3,80}"'))}`:''}${field('Прізвище та ім’я (для вчителя також по батькові)',input('name',u?.name||'','required'))}${field('Клас учня',`<select name="className"><option value="">Оберіть клас</option>${options(S.catalog.filter(x=>x.kind==='class').map(x=>x.name),u?.class_name)}</select>`)}${field('Предмети вчителя · через кому',input('subjects',u?.subjects.join(', ')||'','list="user-subjects"'))}<datalist id="user-subjects">${options(S.catalog.filter(x=>x.kind==='subject').map(x=>x.name))}</datalist><button class="primary wide">${u?'Зберегти':'Створити'}</button></form>`);}
function catalog(){return `${heading('АДМІНІСТРУВАННЯ','Класи та предмети','Довідники для профілів і запуску тестування.',button('Видалені','openDeleted','outline'))}<div class="two-columns">${['class','subject'].map(kind=>`<section class="panel"><h2>${kind==='class'?'Класи':'Предмети'}</h2><ul class="catalog-list">${S.catalog.filter(x=>x.kind===kind).map(x=>`<li><span>${h(x.name)}</span>${button('Видалити','trashCatalog','text-button danger',`data-id="${x.id}"`)}</li>`).join('')}</ul><form data-form="catalog" data-kind="${kind}">${field('Додати назву',input('name','','required placeholder="'+(kind==='class'?'Наприклад, 7-Б':'Наприклад, Інформатика')+'"'))}<button class="primary">Додати</button></form></section>`).join('')}</div>`;}
function settings(){return `${heading('ОСОБИСТИЙ ПРОСТІР','Налаштування','Керуйте своїм доступом до КіберДому.')}<section class="panel narrow"><h2>Змінити пароль</h2>${S.user.must_change?'<p class="alert">Перед початком роботи замініть тимчасовий пароль.</p>':''}<form data-form="password">${field('Поточний пароль',input('currentPassword','','type="password" autocomplete="current-password" required'))}${field('Новий пароль · щонайменше 10 символів',input('newPassword','','type="password" minlength="10" maxlength="128" autocomplete="new-password" required'))}${field('Повторіть новий пароль',input('repeat','','type="password" autocomplete="new-password" required'))}<button class="primary">Змінити пароль</button></form></section>`;}
function picture(url,cls='question-image'){return url?`<img class="${cls}" src="${h(url)}" alt="Зображення до завдання" referrerpolicy="no-referrer" loading="lazy">`:'';}
function answerTone(q,id){if(!S.review)return '';const c=S.review.correct;const good=q.type==='single'?c===id:Array.isArray(c)&&c.includes(id);const picked=S.draft===id||Array.isArray(S.draft)&&S.draft.includes(id);return good?'revealed-correct':picked?'revealed-wrong':'';}
function choices(q){if(['single','multi'].includes(q.type))return `<div class="answer-grid">${q.options.map((o,i)=>`<button class="answer ${answerTone(q,o.id)} ${S.draft===o.id||Array.isArray(S.draft)&&S.draft.includes(o.id)?'chosen':''}" data-act="choose" data-id="${h(o.id)}" ${S.review?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span>${picture(o.image,'answer-image')}${richText(o.text,o.format)}</button>`).join('')}</div>`;
if(q.type==='sequence')return `<div class="sequence-list">${(S.draft||q.options.map(o=>o.id)).map((id,i)=>{const o=q.options.find(x=>x.id===id);return `<div class="sequence-item" draggable="${!S.review}" data-drag="${h(id)}"><span class="option-letter">${i+1}</span>${picture(o.image,'answer-thumb')}${richText(o.text,o.format)}<div>${button('↑','moveUp','outline',`data-index="${i}" aria-label="Перемістити вище" ${i===0||S.review?'disabled':''}`)}${button('↓','moveDown','outline',`data-index="${i}" aria-label="Перемістити нижче" ${i===q.options.length-1||S.review?'disabled':''}`)}</div></div>`}).join('')}</div>`;
if(q.type==='match')return `<div class="match-list">${q.options.map(o=>`<label>${picture(o.image,'answer-thumb')}${richText(o.text,o.format)}<select data-answer-map="${o.id}" ${S.review?'disabled':''}><option value="">Оберіть пару</option>${q.groups.map(g=>`<option value="${h(g)}" ${S.draft?.[o.id]===g?'selected':''} ${Object.entries(S.draft||{}).some(([id,v])=>id!==o.id&&v===g)?'disabled':''}>${h(g)}</option>`).join('')}</select></label>`).join('')}</div>`;
return `<p class="small">Обери слово, потім натисни на категорію. Зайві слова залиш у хмарі.</p><div class="word-cloud" data-drop=""><h3>Хмара слів</h3>${q.options.filter(o=>!S.draft?.[o.id]).map(wordChip).join('')}</div><div class="category-grid">${q.groups.map(g=>`<section class="category" data-drop="${h(g)}"><button class="category-title" data-act="putWord" data-group="${h(g)}" ${S.review?'disabled':''}>${h(g)}</button>${q.options.filter(o=>S.draft?.[o.id]===g).map(wordChip).join('')}</section>`).join('')}</div>${button('Повернути вибране слово у хмару','putWord','text-button','data-group=""')}`;}
function wordChip(o){return `<button class="word ${S.selectedWord===o.id?'chosen':''}" draggable="${!S.review}" data-drag="${o.id}" data-act="selectWord" data-id="${o.id}" ${S.review?'disabled':''}>${picture(o.image,'answer-thumb')}${richText(o.text,o.format)}</button>`;}
function correctText(q,c){const name=id=>q.options.find(o=>o.id===id)?.text||'Зображення';if(q.type==='single')return name(c);if(Array.isArray(c))return c.map(name).join('\n\n');return Object.entries(c).map(([id,v])=>`${name(id)}: ${v||'зайве слово'}`).join('; ');}
function player(){const p=S.play;if(!p)return '';let body;if(p.done&&!S.review)body=`<section class="panel final-report">${reportView(p.result,p.title,p.scale)}${button('До головної','leavePlay','primary')}</section>`;else if(p.status==='paused')body=`<section class="freeze panel"><span class="badge blue">Учитель призупинив тест</span><div class="ice"><img src="./assets/bee-wave.gif" alt="Бджілка у крижинці"></div><h1>Знання зачекають</h1><p>Твій час зупинено. Відповіді збережено.<br>Продовжимо, щойно вчитель відновить сеанс.</p></section>`;else if(p.stopped)body=`<section class="panel empty"><h1>${p.status==='cancelled'?'Сеанс скасовано':'Сеанс завершено'}</h1><p>Робота не була завершена, тому оцінку не виставлено.</p>${button('На головну','leavePlay')}</section>`;else {const q=p.question;body=`<div class="player-heading"><span class="badge blue">${h(p.subject)}</span><span>Запитання ${p.index+1} із ${p.count}</span>${p.timer?'<span class="timer" id="timer">…</span>':''}</div><progress class="quiz-progress" value="${p.index}" max="${p.count}"></progress><section class="panel question-card"><div class="question-meta"><span>${TYPES[q.type]}</span><span>${q.points} ${q.points===1?'бал':'балів'}</span></div><h1 class="content-text ${q.format==='code'?'code-text':''}">${h(q.text)}</h1>${picture(q.image)}${choices(q)}${S.review?`<div class="answer-feedback ${S.review.points===S.review.max?'correct':'incorrect'}"><b>${S.review.expired?'Час вичерпано. ':''}${S.review.points} / ${S.review.max} балів</b><p>Правильна відповідь:</p>${richText(correctText(q,S.review.correct),q.options.some(o=>o.format==='code')?'code':'text')}${S.review.explanation?`<p class="content-text">${h(S.review.explanation)}</p>`:''}</div>${button('Продовжити','nextQuestion','primary wide')}`:button('Підтвердити відповідь','answer','primary wide',S.sending?'disabled':'')}</section>`;}return `<div class="player"><header>${brand}<span>${h(p.name)} · ${h(p.className)}</span></header><main>${body}</main></div>`;}
function render(){clearInterval(timer);$('#app').innerHTML=S.view==='play'?player():S.view==='entry'?entry():S.view==='simulators'&&!S.user?simUI.guest():shell(({simulators:simUI.view,home,tests,builder,live,journal,users,catalog,settings,chart:achievements}[S.view]||home)());if(S.view==='play')startTimer();requestAnimationFrame(layoutHoneycomb);}
function initDraft(){const q=S.play?.question;S.draft=q?.type==='sequence'?q.options.map(o=>o.id):q?.type==='multi'?[]:['match','groups'].includes(q?.type)?Object.fromEntries(q.options.map(o=>[o.id,''])):null;S.selectedWord=null;}
function setPlay(p){const old=S.play;S.play=p;S.clockAt=performance.now();S.clockRemaining=p.remainingMs;if(!old||old.index!==p.index)initDraft();}
function startTimer(){if(!S.play?.timer||S.play.status!=='active'||S.play.done||S.review)return;const tick=()=>{const ms=Math.max(0,S.clockRemaining-(performance.now()-S.clockAt));if($('#timer')){$('#timer').textContent=Math.ceil(ms/1000)+' с';$('#timer').classList.toggle('urgent',ms<10000);}if(ms<=0&&!S.sending)answer(true);};tick();timer=setInterval(tick,250);}
async function refreshPlay(){if(!S.attempt||S.sending||pollBusy)return;pollBusy=true;try{if(S.review){const r=await api('attemptStatus',{attemptToken:S.attempt});if(!r.done&&r.status!==S.play.status){S.play.status=r.status;S.play.stopped=['closed','cancelled'].includes(r.status);if(S.play.stopped)S.review=null;render();}}else{const p=await api('state',{attemptToken:S.attempt}),changed=!S.play||p.index!==S.play.index||p.status!==S.play.status||p.done!==S.play.done;setPlay(p);if(changed)render();}}catch(e){toast(e.message)}finally{pollBusy=false;}}
async function answer(timeout=false){if(S.sending||S.review||S.play.status!=='active')return;S.sending=true;const btn=$('[data-act="answer"]');if(btn)btn.disabled=true;try{const r=await api('answer',{attemptToken:S.attempt,index:S.play.index,value:timeout?null:S.draft});S.sending=false;if(r.feedback){S.review=r.feedback;render();}else{setPlay(await api('state',{attemptToken:S.attempt}));render();}}catch(e){toast(e.message);S.sending=false;await refreshPlay();if(btn)btn.disabled=false;}finally{S.sending=false;}}
async function loadDashboard(){S.catalog=(await api('catalog')).items;if(S.user.role==='student')S.results=(await api('history')).results;else{const r=await api('tests');S.tests=r.tests;S.sessions=r.sessions;}}
async function navigate(view){if(S.edit&&S.view==='builder'&&view!=='builder'&&!confirm('Вийти з конструктора? Незбережені зміни буде втрачено.'))return;if(S.user?.must_change)view='settings';S.view=view;S.filter='';if(['home','tests','live','chart'].includes(view)){await loadDashboard();if(view==='live')S.live=null;}if(view==='simulators')await simUI.load();if(view==='catalog')S.catalog=(await api('catalog')).items;if(view==='journal')S.journal=await api('journal');if(view==='users')S.users=(await api('users')).users;render();}
function csv(filename,rows){const value=x=>{let s=String(x??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const blob=new Blob(['\ufeff'+rows.map(r=>r.map(value).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function launchModal(id){const t=S.tests.find(x=>x.id===id)?.data;modal(`<h2>Запустити тест</h2><p>${h(t.title)}</p><form data-form="launch" data-id="${id}"><div class="class-grid">${S.catalog.filter(x=>x.kind==='class').map(x=>`<label class="check-label"><input type="checkbox" name="classes" value="${h(x.name)}">${h(x.name)}</label>`).join('')||'<p>Спершу адміністратор має додати класи.</p>'}</div><p class="small">Учні отримають випадкову вибірку за налаштуваннями. Сеанс з’явиться в журналі.</p><button class="primary wide">Створити сеанс і PIN-код</button></form>`);}
async function click(e){const el=e.target.closest('[data-act]');if(!el)return;e.preventDefault();const a=el.dataset.act,id=el.dataset.id,q=S.edit?.questions[S.qi];try{if(await resultUI.click(a,el))return;if(await simUI.click(a,el))return;if(await adminUI.click(a,el))return;switch(a){
case 'brand':if(S.view==='play')return;await navigate(S.user?'home':'entry');break;
case 'loginToggle':S.loginMode=!S.loginMode;render();break;
case 'resetLookup':S.lookup=null;render();break;
case 'nav':await navigate(el.dataset.view);break;
case 'logout':await api('logout');S.token='';S.user=null;sessionStorage.removeItem('kd-auth');S.view='entry';S.loginMode=false;render();break;
case 'newTest':freshTest();break;
case 'editTest':S.edit=structuredClone(S.tests.find(t=>t.id===id).data);S.qi=0;S.view='builder';render();break;
case 'saveTest':{el.disabled=true;const r=await api('saveTest',{test:S.edit});S.edit=r.test;await loadDashboard();toast('Тест збережено.');render();break;}
case 'selectQuestion':S.qi=Number(el.dataset.index);render();break;
case 'addQuestion':S.edit.questions.push(newQuestion('single',el.dataset.sectionId||q.section));S.qi=S.edit.questions.length-1;render();break;
case 'deleteQuestion':if(confirm('Видалити це запитання?')){S.edit.questions.splice(S.qi,1);S.qi=Math.min(S.qi,S.edit.questions.length-1);render();}break;
case 'changeType':if(q.type!==el.dataset.type){if(q.text&&!confirm('Змінити тип? Варіанти та ключ відповідей буде скинуто.'))break;Object.assign(q,newQuestion(el.dataset.type,q.section),{id:q.id,text:q.text,format:q.format,image:q.image,points:q.points});render();}break;
case 'addOption':{const o={id:uid(),text:'',image:''};q.options.push(o);if(q.type==='sequence')q.correct=q.options.map(o=>o.id);if(['match','groups'].includes(q.type))q.correct[o.id]=q.type==='groups'?'':q.groups[0];render();break;}
case 'removeOption':{const [o]=q.options.splice(Number(el.dataset.index),1);if(q.type==='single'&&q.correct===o.id)q.correct=q.options[0]?.id;if(Array.isArray(q.correct))q.correct=q.correct.filter(x=>x!==o.id);else if(typeof q.correct==='object')delete q.correct[o.id];render();break;}
case 'optionUp':case 'optionDown':{const i=Number(el.dataset.index),j=i+(a==='optionUp'?-1:1);[q.options[i],q.options[j]]=[q.options[j],q.options[i]];q.correct=q.options.map(o=>o.id);render();break;}
case 'sections':sectionModal();break;
case 'addSection':S.edit.sections.push({id:uid(),name:'Новий розділ',take:0,uniqueTypes:false,advice:''});sectionModal();break;
case 'doneSections':$('#modal').close();render();break;
case 'closeModal':$('#modal').close();break;
case 'launch':await launchModal(id);break;
case 'openSession':S.live=await api('sessionReport',{id});S.view='live';render();break;
case 'backLive':await navigate('live');break;
case 'copyInvite':await navigator.clipboard.writeText(location.origin+location.pathname+'?pin='+S.live.session.code);toast('Посилання скопійовано.');break;
case 'confirmEnd':modal(`<h2>${el.dataset.command==='cancel'?'Скасувати сеанс?':'Завершити сеанс?'}</h2><p>Учні більше не зможуть продовжити незавершені роботи. Вже отримані оцінки збережуться.</p>${button('Підтвердити','sessionCommand','primary',`data-command="${el.dataset.command}"`)}`);break;
case 'sessionCommand':await api('sessionAction',{id:S.live.session.id,command:el.dataset.command});$('#modal').close();S.live=await api('sessionReport',{id:S.live.session.id});render();break;
case 'studentReport':{const x=S.live.students.find(x=>x.id===id);modal(reportView(x.result,x.name,S.live.session.scale)+resultUI.removeButton('result',x.id,'Видалити цей результат'));break;}
case 'historyReport':{const x=S.results.find(x=>x.id===id);modal(reportView(x,x.title));break;}
case 'exportLive':csv('kiberdim-results.csv',[['Учень','Клас','Бал','Рівень','Відсоток'],...S.live.students.map(x=>[x.name,x.className,x.result?.mark,x.result?.level,x.result?.percent])]);break;
case 'exportJournal':csv('kiberdim-journal.csv',[['Учень','Клас',...S.journal.columns.map(c=>c.title+' '+date(c.date))],...S.journal.rows.map(r=>[r.name,r.className,...S.journal.columns.map(c=>{const x=r.cells[c.id];return x?.status==='done'?(c.scale==='level'?x.level:x.mark):x?.status==='cancelled'?'С':''})])]);break;
case 'newUser':userModal();break;
case 'editUser':userModal(id);break;
case 'resetUser':if(confirm('Створити новий тимчасовий пароль? Попередній перестане працювати.')){const r=await api('userReset',{id});modal(`<h2>Новий тимчасовий пароль</h2><p>Логін: <b>${h(r.login)}</b></p><code class="temporary">${h(r.temporaryPassword)}</code><p>Передайте користувачу. Після закриття пароль більше не відображатиметься.</p>`);}break;
case 'blockUser':{const u=S.users.find(x=>x.id===id);if(confirm(u.blocked?'Відновити доступ?':'Призупинити доступ користувача?')){await api('userBlock',{id,blocked:!u.blocked});await navigate('users');}break;}
case 'joinFromProfile':S.view='entry';S.loginMode=false;S.lookup=null;render();break;
case 'choose':if(S.review||S.play.status!=='active')break;if(S.play.question.type==='single')S.draft=id;else S.draft=S.draft.includes(id)?S.draft.filter(x=>x!==id):[...S.draft,id];render();break;
case 'moveUp':case 'moveDown':{if(S.review)break;const i=Number(el.dataset.index),j=i+(a==='moveUp'?-1:1);[S.draft[i],S.draft[j]]=[S.draft[j],S.draft[i]];render();break;}
case 'selectWord':if(!S.review){S.selectedWord=id;render();}break;
case 'putWord':if(!S.review&&S.selectedWord){S.draft[S.selectedWord]=el.dataset.group;S.selectedWord=null;render();}break;
case 'answer':await answer();break;
case 'nextQuestion':S.review=null;setPlay(await api('state',{attemptToken:S.attempt}));render();break;
case 'leavePlay':S.attempt='';S.play=null;S.review=null;sessionStorage.removeItem('kd-attempt');await navigate(S.user?'home':'entry');break;
}}catch(err){toast(err.message);el.disabled=false;}}
const resultUI=resultTrashTools({S,api,modal,button,h,toast,loadDashboard,render});
const simUI=simulatorTools({S,api,modal,button,field,h,toast,navigate,render,heading,brand});
const adminUI=adminTools({S,api,modal,button,field,h,toast,navigate,loadDashboard,render});
document.addEventListener('click',click);
document.addEventListener('input',e=>{const x=e.target,q=S.edit?.questions[S.qi];if(x.dataset.test)S.edit[x.dataset.test]=x.type==='checkbox'?x.checked:x.type==='number'?Number(x.value):x.value;if(x.dataset.q){q[x.dataset.q]=x.type==='number'?Number(x.value):x.dataset.q==='groups'?x.value.split('\n'):x.value;}if(x.dataset.option!==undefined)q.options[Number(x.dataset.option)][x.dataset.key]=x.value;if(x.dataset.correct){if(q.type==='single')q.correct=x.dataset.correct;else q.correct=x.checked?[...new Set([...q.correct,x.dataset.correct])]:q.correct.filter(id=>id!==x.dataset.correct);}if(x.dataset.map)q.correct[x.dataset.map]=x.value;if(x.dataset.section!==undefined)S.edit.sections[Number(x.dataset.section)][x.dataset.key]=x.type==='checkbox'?x.checked:x.type==='number'?Number(x.value):x.value;if(S.view==='builder'&&(x.dataset.q||x.dataset.section!==undefined)){refreshBuilderSections();}if(x.dataset.q==='format'){document.querySelector('[data-q="text"]').classList.toggle('code-editor',x.value==='code');}if(x.dataset.option!==undefined&&x.dataset.key==='format'){x.closest('.editor-option').querySelector('textarea').classList.toggle('code-editor',x.value==='code');}if(x.id==='search'){S.filter=x.value;$('#test-list').innerHTML=testCards(S.tests.filter(t=>(t.data.title+' '+t.data.topic).toLowerCase().includes(S.filter.toLowerCase())));}});
document.addEventListener('change',e=>{const x=e.target;if(x.dataset.answerMap&&!S.review){S.draft[x.dataset.answerMap]=x.value;render();}if(x.id==='journal-class'){S.classFilter=x.value;render();}if(x.dataset.q==='groups'){const v=x.value.split('\n').map(x=>x.trim()).filter(Boolean);S.edit.questions[S.qi].groups=v;render();}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();const b=Object.fromEntries(new FormData(f)),btn=f.querySelector('button[type="submit"],button:not([type])');if(btn)btn.disabled=true;try{switch(f.dataset.form){case 'login':{const r=await api('login',b);S.user=r.user;S.token=r.token;sessionStorage.setItem('kd-auth',S.token);if(!S.user.must_change)await loadDashboard();S.view=S.user.must_change?'settings':'home';render();break;}case 'lookup':S.code=b.code;S.lookup=await api('lookup',b);render();break;case 'join':{const r=await api('join',b);S.attempt=r.attemptToken;sessionStorage.setItem('kd-attempt',S.attempt);S.review=null;S.play=null;setPlay(r);S.view='play';render();break;}case 'launch':{const r=await api('launch',{id:f.dataset.id,classes:new FormData(f).getAll('classes')});$('#modal').close();S.live=await api('sessionReport',{id:r.session.id});S.view='live';render();break;}case 'catalog':await api('catalogAdd',{...b,kind:f.dataset.kind});await loadDashboard();render();break;case 'user':{const r=await api(f.dataset.id?'userUpdate':'userCreate',{...b,id:f.dataset.id,subjects:b.subjects.split(',').map(x=>x.trim()).filter(Boolean)});$('#modal').close();await navigate('users');if(r.temporaryPassword)modal(`<h2>Обліковий запис створено</h2><p>Логін: <b>${h(b.login)}</b></p><code class="temporary">${h(r.temporaryPassword)}</code><p>Збережіть і передайте тимчасовий пароль користувачу. Під час першого входу його потрібно змінити.</p>`);break;}case 'password':if(b.newPassword!==b.repeat)throw Error('Нові паролі не збігаються.');{const r=await api('changePassword',b);S.token=r.token;S.user=r.user;sessionStorage.setItem('kd-auth',S.token);await loadDashboard();toast('Пароль змінено.');render();break;}}}catch(err){toast(err.message)}finally{if(btn)btn.disabled=false;}});
let dragId=null;document.addEventListener('dragstart',e=>{const el=e.target.closest('[data-drag]');if(!el||S.review)return;dragId=el.dataset.drag;e.dataTransfer.setData('text/plain',dragId);});document.addEventListener('dragover',e=>{if(e.target.closest('[data-drop],.sequence-item'))e.preventDefault();});document.addEventListener('drop',e=>{if(!dragId||S.review||S.play?.status!=='active')return;const target=e.target.closest('[data-drop],.sequence-item');if(!target)return;e.preventDefault();if(S.play.question.type==='groups')S.draft[dragId]=target.dataset.drop;else if(S.play.question.type==='sequence'){const from=S.draft.indexOf(dragId),to=S.draft.indexOf(target.dataset.drag);if(from<0||to<0)return;S.draft.splice(to,0,S.draft.splice(from,1)[0]);}dragId=null;render();});
setInterval(async()=>{if(document.hidden)return;if(S.view==='play')return refreshPlay();if(S.view==='live'&&S.live&&['active','paused'].includes(S.live.session.status)&&!pollBusy&&!$('#modal').open){pollBusy=true;try{S.live=await api('sessionReport',{id:S.live.session.id});render();}catch(e){toast(e.message)}finally{pollBusy=false;}}},4000);
(async()=>{render();try{if(S.token){S.user=(await api('me')).user;if(!S.user){S.token='';sessionStorage.removeItem('kd-auth');}else if(S.user.must_change){S.view='settings';render();return;}else{await loadDashboard();S.view='home';}}if(new URLSearchParams(location.search).get('view')==='simulators'){S.view='simulators';await simUI.load();}else if(S.attempt){setPlay(await api('state',{attemptToken:S.attempt}));S.view='play';}render();}catch(e){toast(e.message);S.attempt='';sessionStorage.removeItem('kd-attempt');render();}})();

function layoutHoneycomb(){document.querySelectorAll('.honeycomb').forEach(box=>{const cells=[...box.children];if(!cells.length)return;const width=box.clientWidth,gap=12,cols=Math.min(cells.length,Math.max(1,Math.floor((width+gap)/192)));const w=Math.min(205,(width-gap*(cols-1))/(cols+(cols>1?.5:0))),hh=w*2/Math.sqrt(3),stepX=w+gap,stepY=hh*.75+gap;let maxBottom=0;cells.forEach((cell,i)=>{const row=Math.floor(i/cols),col=i%cols,rowCount=Math.min(cols,cells.length-row*cols),offset=cols>1&&row%2?stepX/2:0,total=rowCount*stepX-gap+(cols>1?stepX/2:0),left=(width-total)/2+col*stepX+offset;Object.assign(cell.style,{position:'absolute',width:w+'px',height:hh+'px',left:left+'px',top:row*stepY+'px',transform:'none'});maxBottom=Math.max(maxBottom,row*stepY+hh);});box.style.height=maxBottom+'px';});}
window.addEventListener('resize',layoutHoneycomb);

document.addEventListener('keydown',e=>{const el=e.target;if(!el.matches('textarea[data-preserve].code-editor'))return;if(e.key==='Escape'){el.dataset.tabNavigate='true';e.stopPropagation();return;}if(e.key!=='Tab')return;if(el.dataset.tabNavigate){delete el.dataset.tabNavigate;return;}if(e.ctrlKey||e.metaKey||e.altKey)return;e.preventDefault();const result=indentSelection(el.value,el.selectionStart,el.selectionEnd,e.shiftKey);el.value=result.value;el.setSelectionRange(result.start,result.end);el.dispatchEvent(new Event('input',{bubbles:true}));});
